import{_ as t}from"./chunks/my-system.CS4oEI92.js";import{_ as a,o as s,c as o,ag as r}from"./chunks/framework.DqVSm8kp.js";const p=JSON.parse('{"title":"My System","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/system.md","filePath":"en/guide/system.md"}'),i={name:"en/guide/system.md"};function n(l,e,d,c,m,u){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="my-system" tabindex="-1">My System <a class="header-anchor" href="#my-system" aria-label="Permalink to &quot;My System&quot;">​</a></h1><p>The System page shows real hardware specifications and live Ollama status — actual data from your OS, not browser estimates.</p><p><strong>Sidebar item:</strong> My System <strong>Route:</strong> <code>/system</code></p><p><img src="'+t+'" alt="My System interface"></p><h2 id="hardware-detection" tabindex="-1">Hardware Detection <a class="header-anchor" href="#hardware-detection" aria-label="Permalink to &quot;Hardware Detection&quot;">​</a></h2><p>LLMxRay uses a custom Vite plugin (<code>vite-plugin-system-info</code>) that queries the operating system directly:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Detection method</th></tr></thead><tbody><tr><td><strong>Windows</strong></td><td>PowerShell commands</td></tr><tr><td><strong>Linux</strong></td><td><code>/proc</code> filesystem + <code>lspci</code></td></tr><tr><td><strong>macOS</strong></td><td><code>sysctl</code> commands</td></tr></tbody></table><h3 id="displayed-information" tabindex="-1">Displayed Information <a class="header-anchor" href="#displayed-information" aria-label="Permalink to &quot;Displayed Information&quot;">​</a></h3><ul><li><strong>CPU</strong> — Model name, core count, architecture</li><li><strong>RAM</strong> — Total installed memory with live usage</li><li><strong>GPU</strong> — Model name, VRAM, driver version</li><li><strong>Storage</strong> — Disk capacity and available space</li></ul><div class="tip custom-block"><p class="custom-block-title">First-time setup</p><p>Hardware information is read when the Vite dev server starts. If the System page shows &quot;Restart dev server&quot;, stop and restart <code>npm run dev</code>.</p></div><h2 id="ollama-status" tabindex="-1">Ollama Status <a class="header-anchor" href="#ollama-status" aria-label="Permalink to &quot;Ollama Status&quot;">​</a></h2><p>The Ollama section shows:</p><ul><li><strong>Connection status</strong> — Whether Ollama is reachable</li><li><strong>Running models</strong> — Which models are currently loaded in memory</li><li><strong>Memory allocation</strong> — How much RAM/VRAM each loaded model is using</li><li><strong>Inference settings</strong> — Default parameters for the running instance</li></ul><h2 id="storage-usage" tabindex="-1">Storage Usage <a class="header-anchor" href="#storage-usage" aria-label="Permalink to &quot;Storage Usage&quot;">​</a></h2><p>A visualization of IndexedDB storage used by LLMxRay:</p><ul><li>Total storage used by the origin</li><li>Breakdown by database (conversations, benchmarks, RAG vectors, training data)</li><li>Visual percentage bar</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>High RAM usage?</strong> — Ollama keeps models in memory after first use. Use smaller quantized models (Q4) or reduce context length in Settings.</li><li><strong>GPU not detected?</strong> — Make sure your GPU drivers are up to date. On Linux, ensure <code>lspci</code> is available.</li><li>The storage visualization refreshes automatically when you navigate to this page.</li></ul>',18)])])}const y=a(i,[["render",n]]);export{p as __pageData,y as default};
